import sys

sys.setrecursionlimit(100000)


class _CalcError(Exception):
    pass


def calc(expr: str) -> int | str:
    s = expr
    n = len(s)
    i = 0

    def skip():
        nonlocal i
        while i < n and s[i] == " ":
            i += 1

    def tdiv(a, b):
        q = abs(a) // abs(b)
        return -q if (a < 0) != (b < 0) else q

    def tmod(a, b):
        return a - b * tdiv(a, b)

    def parse_expr():
        v = parse_term()
        while True:
            skip()
            if i < n and s[i] in "+-":
                op = s[i]
                i += 1
                r = parse_term()
                v = v + r if op == "+" else v - r
            else:
                return v

    def parse_term():
        v = parse_unary()
        while True:
            skip()
            if i < n and s[i] in "*/%":
                op = s[i]
                i += 1
                r = parse_unary()
                if op == "*":
                    v = v * r
                elif op == "/":
                    if r == 0:
                        raise _CalcError()
                    v = tdiv(v, r)
                else:
                    if r == 0:
                        raise _CalcError()
                    v = tmod(v, r)
            else:
                return v

    def parse_unary():
        nonlocal i
        skip()
        neg = False
        while i < n and s[i] == "-":
            neg = not neg
            i += 1
            skip()
        v = parse_power()
        return -v if neg else v

    def parse_power():
        nonlocal i
        base = parse_primary()
        skip()
        if i < n and s[i] == "^":
            i += 1
            exp = parse_unary()
            if exp < 0:
                raise _CalcError()
            return pow(base, exp)
        return base

    def parse_primary():
        nonlocal i
        skip()
        if s[i] == "(":
            i += 1
            v = parse_expr()
            skip()
            i += 1  # consume ')'
            return v
        j = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[j:i])

    try:
        return parse_expr()
    except _CalcError:
        return "error"
